<?php if(Ctx::can('cheque.approve')&&$ch['status']!=='void'): ?><form method="post" class="erp-form"><?php self::form('module_cheque_transition',$cid,'cheques',$ch['id']); ?><input type="hidden" name="revision" value="<?php echo (int)$ch['revision']; ?>"><label>وضعیت تازه<select name="status"><?php $next=['pending'=>['collected','returned','void'],'collected'=>['returned','void'],'returned'=>['void']][$ch['status']];foreach($next as $key): ?><option value="<?php echo esc_attr($key); ?>"><?php echo esc_html(TreasuryService::CHEQUE_STATES[$key]); ?></option><?php endforeach; ?></select></label><label>تاریخ شمسی<input name="event_date" value="<?php echo esc_attr(Jalali::format(Jalali::today(),false)); ?>" required data-jalali dir="ltr"></label><label>دلیل<input name="reason" required minlength="5" maxlength="300"></label><button type="submit" class="btn btn-outline btn-sm">ثبت رویداد و اثر حسابداری</button></form><?php endif; ?>
